/* A small interactive layer. All demos are local illustrations, not service calls. */
const labModes={
  platforms:{location:'access.platform',icon:'↗',domain:'INTERFACE → INFRASTRUCTURE',title:'Built to connect.',key:'product_access',value:'ready to explore',description:'Explore how an interface connects identity, licensing, and product access.',steps:['Request','Identity','Access'],messages:['Request validated.','Identity and plan resolved.','Product access returned.'],satellite:'<React />',satellite2:'API'},
  desktop:{location:'operator.desktop',icon:'∿',domain:'HARDWARE → HUMAN INSIGHT',title:'Keep it responsive.',key:'measurement_stream',value:'ready to explore',description:'Explore how background acquisition keeps a scientific interface responsive.',steps:['Acquire','Process','Visualize'],messages:['Illustrative measurement acquired.','Analysis completed in a background worker.','Interface updated with the result.'],satellite:'PySide6',satellite2:'I/O'},
  data:{location:'data.foundation',icon:'▤',domain:'DATA → DEPENDABLE WORKFLOWS',title:'Make state matter.',key:'operation_state',value:'ready to explore',description:'Explore validation, a database transaction, and an auditable result.',steps:['Validate','Commit','Audit'],messages:['Input checked against a contract.','Illustrative transaction committed.','Outcome recorded for traceability.'],satellite:'SQL',satellite2:'STATE'}
};
let labMode='platforms',labTimers=[],labRunning=false;
const scene=document.querySelector('.workbench-scene'),runButton=document.querySelector('#run-demo');
function clearLabTimers(){labTimers.forEach(clearTimeout);labTimers=[];}
function selectLab(mode){clearLabTimers();labRunning=false;labMode=mode;const data=labModes[mode];scene.dataset.scene=mode;document.querySelectorAll('[data-lab]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lab===mode)));for(const [id,value] of Object.entries({'demo-location':data.location,'demo-icon':data.icon,'demo-domain':data.domain,'demo-title':data.title,'demo-key':data.key,'demo-value':data.value,'lab-description':data.description})){document.getElementById(id).textContent=value;}data.steps.forEach((label,index)=>document.getElementById(`step-${index}`).textContent=label);document.querySelector('.sat-one').textContent=data.satellite;document.querySelector('.sat-two').textContent=data.satellite2;document.querySelectorAll('[data-step]').forEach(node=>node.classList.remove('step-active','step-done'));document.querySelector('#lab-status').textContent='Interactive concept · no live service calls';runButton.disabled=false;runButton.innerHTML='Run the flow <span aria-hidden="true">↗</span>';}
document.querySelectorAll('[data-lab]').forEach(button=>button.addEventListener('click',()=>selectLab(button.dataset.lab)));
runButton.addEventListener('click',()=>{if(labRunning)return;clearLabTimers();labRunning=true;runButton.disabled=true;runButton.textContent='Running…';const data=labModes[labMode];document.querySelectorAll('[data-step]').forEach(node=>node.classList.remove('step-active','step-done'));const step=(index)=>{document.querySelectorAll('[data-step]').forEach((node,i)=>{node.classList.toggle('step-active',i===index);node.classList.toggle('step-done',i<index);});document.querySelector('#lab-status').textContent=data.messages[index];document.querySelector('#demo-value').textContent=index===2?'flow complete':'processing…';if(index===2){runButton.disabled=false;runButton.innerHTML='Run again <span aria-hidden="true">↗</span>';labRunning=false;}};if(reducedMotion.matches||paused){step(2);}else{step(0);labTimers.push(setTimeout(()=>step(1),650),setTimeout(()=>step(2),1300));}});
document.querySelector('#motion-toggle').addEventListener('click',()=>{if(paused){scene.style.setProperty('--tilt-x','0deg');scene.style.setProperty('--tilt-y','0deg');}});
let tiltFrame=0;scene.addEventListener('pointermove',event=>{if(event.pointerType==='touch'||reducedMotion.matches||paused)return;cancelAnimationFrame(tiltFrame);const rect=scene.getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;tiltFrame=requestAnimationFrame(()=>{scene.style.setProperty('--tilt-x',`${-y*5}deg`);scene.style.setProperty('--tilt-y',`${x*6}deg`);});});scene.addEventListener('pointerleave',()=>{cancelAnimationFrame(tiltFrame);scene.style.setProperty('--tilt-x','0deg');scene.style.setProperty('--tilt-y','0deg');});

