const projectDialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project-open]').forEach(button=>button.addEventListener('click',()=>{const data=projectDetails[button.dataset.projectOpen];for(const field of ['label','title','intro','problem','focus','scope'])document.querySelector(`#project-dialog-${field}`).textContent=data[field];document.querySelector('#project-dialog-tags').replaceChildren(...data.tags.map(tag=>{const element=document.createElement('span');element.textContent=tag;return element;}));document.querySelector('#project-dialog-links').replaceChildren(...data.links.map(([label,href])=>{const a=document.createElement('a');a.href=href;a.textContent=label+' ↗';a.target='_blank';a.rel='noopener';return a;}));projectDialog.showModal();}));
const commandDialog=document.querySelector('#command-dialog'),commandSearch=document.querySelector('#command-search');
function openCommands(){commandDialog.showModal();commandSearch.value='';filterCommands();commandSearch.focus();}
function filterCommands(){let matches=0;document.querySelectorAll('.command-list a').forEach(link=>{link.hidden=!link.textContent.toLowerCase().includes(commandSearch.value.toLowerCase().trim());if(!link.hidden)matches++;});document.querySelector('.command-empty').hidden=matches>0;}
document.querySelector('.command-trigger').addEventListener('click',openCommands);commandSearch.addEventListener('input',filterCommands);document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(commandDialog.open)commandDialog.close();else if(!projectDialog.open)openCommands();}});document.querySelectorAll('.command-list a').forEach(link=>link.addEventListener('click',()=>commandDialog.close()));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
let toastTimer;document.querySelector('#copy-email').addEventListener('click',async()=>{const button=document.querySelector('#copy-email');try{await navigator.clipboard.writeText('mangipudisrikanth03@gmail.com');const toast=document.querySelector('.copy-toast');toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.hidden=true;},2500);}catch{button.textContent='mangipudisrikanth03@gmail.com';}});
const progress=document.querySelector('.reading-progress');let scrollQueued=false;function updateProgress(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?scrollY/max:0})`;if(scrollY+150<document.querySelector('#work').offsetTop){document.querySelectorAll('.main-nav a').forEach(link=>link.removeAttribute('aria-current'));}scrollQueued=false;}addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateProgress);}},{passive:true});addEventListener('resize',updateProgress);updateProgress();
if('IntersectionObserver' in window){const navLinks=document.querySelectorAll('.main-nav a');const activeObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(link=>{if(link.getAttribute('href')===`#${entry.target.id}`)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}});},{rootMargin:'-15% 0px -55% 0px',threshold:0});document.querySelectorAll('#work,#projects,#about,#contact').forEach(section=>activeObserver.observe(section));if(!reducedMotion.matches){const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);}});},{threshold:.05});document.querySelectorAll('.experience-list>article,.project-card,.about-content').forEach(element=>{element.classList.add('motion-entry');revealObserver.observe(element);});}}
